function App() {
  return (
    <div className="min-h-screen flex flex-col justify-center items-center bg-gradient-to-br from-blue-500 to-purple-600">
      <h1 className="text-5xl font-extrabold text-white mb-6 animate-bounce">
        ¡Tailwind funciona!
      </h1>
      <button className="px-8 py-4 bg-white text-blue-700 font-bold rounded-xl shadow-lg hover:bg-blue-200 transition">
        Prueba de botón
      </button>
    </div>
  );
}
export default App;
